-- Keep one canonical copy of the catalog metadata discrepancy note.
update public.data_sources
set notes='Страница набора обновлена 28.09.2026; заявлены 603 показателя и 33 раздела, включая раздел 31 «Население» и раздел 32 «Занятость и заработная плата». CSV: UTF-8, разделитель «;». Лицензия Creative Commons BY 4.0. Набор преобразован «Если быть точным» из БД ПМО Росстата и является вспомогательной обработанной копией, а не первичным интерфейсом Росстата. Перед импортом сверить код БД ПМО, ОКТМО, тип/границы муниципалитета, год и разрез. Сырые данные в Supabase ещё не импортированы; статус остаётся identified. Контроль версии 30.10.2026: поисковый индекс карточки общего набора показывал обновление 28.09.2026 и охват 2005–2026, однако открытая страница на момент проверки показывала 03.08.2026 и охват 2005–2025. До получения фактической выгрузки верхний год и актуальность не подтверждены; статус остаётся identified.'
where id='tochno_bdmo_2026';
